{
  "architecture_decisions": [
    {
      "dimension": "API Design",
      "recommendation": "Extend the existing GCS client interface to accept an optional byte range parameter, maintaining backward compatibility for full reads.",
      "rationale": "This follows the principle of least surprise and minimizes disruption to existing callers. The parameter can be an Option<Range<u64>> to cleanly handle both full and partial reads.",
      "alternatives_considered": [
        "Creating a separate method like read_object_range()",
        "Requiring users to construct the HTTP range header themselves"
      ],
      "files_affected": [
        "libs/remote_storage/src/gcs_bucket.rs"
      ]
    },
    {
      "dimension": "Error Handling",
      "recommendation": "Implement specific error types for GCS range-related failures (invalid range, range not satisfiable) and propagate them through the existing error handling chain.",
      "rationale": "This provides precise feedback to callers who need to handle GCS-specific errors, such as SafeKeeper when reconciling WAL segments.",
      "alternatives_considered": [
        "Using generic 'RemoteStorageError'",
        "Ignoring range-specific errors and treating them as general I/O failures"
      ],
      "files_affected": [
        "libs/remote_storage/src/gcs_bucket.rs",
        "libs/remote_storage/src/config.rs"
      ]
    },
    {
      "dimension": "HTTP Protocol",
      "recommendation": "Use the standard 'Range' header as specified by RFC 7233, formatted as 'bytes=start-end' for inclusive ranges, and handle the '206 Partial Content' status code correctly.",
      "rationale": "GCS's JSON API is HTTP-compliant, and using standard headers ensures compatibility and proper behavior across all HTTP clients and intermediaries.",
      "alternatives_considered": [
        "Using GCS-specific query parameters for range requests",
        "Implementing a custom non-standard header"
      ],
      "files_affected": [
        "libs/remote_storage/src/gcs_bucket.rs"
      ]
    },
    {
      "dimension": "Testing Strategy",
      "recommendation": "Implement integration tests using the real GCS API to validate byte range functionality, rather than mocking, to ensure correctness against the actual service behavior.",
      "rationale": "GCS's range handling, especially around edge cases and error conditions, is complex. Testing against the real service is the only way to guarantee the implementation meets the operational requirements of SafeKeeper.",
      "alternatives_considered": [
        "Testing only with mock HTTP responses",
        "Relying on unit tests of header formatting only"
      ],
      "files_affected": [
        "libs/remote_storage/tests/test_real_gcs.rs"
      ]
    },
    {
      "dimension": "Performance",
      "recommendation": "Ensure the range request does not inadvertently trigger a full download or cache the entire object in memory before slicing.",
      "rationale": "WAL segments can be large (hundreds of MB). The primary benefit of range reads is avoiding unnecessary I/O and memory pressure for operations that only need small portions of an object.",
      "alternatives_considered": [
        "Downloading the entire object and slicing in-memory",
        "Implementing a caching layer for partial reads"
      ],
      "files_affected": [
        "libs/remote_storage/src/gcs_bucket.rs"
      ]
    }
  ],
